H,W=18,14
G=[[8]*W for _ in range(H)]
shape=[[None,None,None,1,7],[None,1,0,0,1],[7,0,1,1,7]]
# given bbox r2..4 c8..12, mapping offsets -1..1, -2..2
for r,row in enumerate(shape):
 for c,v in enumerate(row):
  if v is not None:G[2+r][8+c]=v
anchors=[(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
for ar,ac in anchors:
 for dr,row in zip(range(-1,2),shape):
  for dc,v in zip(range(-2,3),row):
   if v is not None and 0<=ar+dr<H and 0<=ac+dc<W:G[ar+dr][ac+dc]=v
print(G)
